classDiagram
  class MermaidEngine {
    <<interface>>
    +render(code: string, id: string, theme: Theme) Promise~string~
  }
  class createMermaidEngine {
    +deps: MermaidDeps
    -initialized: Theme | null
    -ensureInit(theme) void
    +render(code, id, theme) Promise~string~
  }
  class DocumentLike {
    <<interface>>
    +getElementById(id) ElementLike | null
  }
  class MermaidLike {
    <<interface>>
    +initialize(config) void
    +render(id, code) Promise~RenderResult~
  }
  createMermaidEngine ..|> MermaidEngine
  createMermaidEngine --> DocumentLike : injetado
  createMermaidEngine --> MermaidLike : injetado

  class Block {
    +index: number
    +kind: string
    +code: string
    +start: number
    +end: number
  }
  class BlockState {
    <<union>>
    idle | loading | ready(svg) | error(message)
  }
  class Renderer {
    <<interface>>
    +update(blocks: Block[], theme: Theme) void
    +retry() void
    +dispose() void
  }
  class createRenderer {
    +sink: RenderSink
    +render: RenderFn
    -tickets: Map~number, number~
    -lastCode: Map~number, string~
    -disposed: boolean
    +update(blocks, theme)
    +retry()
    +dispose()
  }
  class RenderSink {
    <<interface>>
    +setState(index: number, state: BlockState) void
    +setUnavailable(reason: string | null) void
  }
  createRenderer ..|> Renderer
  createRenderer --> RenderSink : alimenta
  createRenderer --> Block : consome
  createRenderer --> BlockState : produz
  Renderer ..> MermaidEngine : RenderFn = engine.render

